import { supabase } from './supabase.js';

const status=document.querySelector('#subscription-success-status'),link=document.querySelector('#subscription-success-link'),loader=document.querySelector('.subscription-loader');
const wait=duration=>new Promise(resolve=>setTimeout(resolve,duration));
async function initialize(){const coaching=new URLSearchParams(location.search).get('offre')==='coaching';const user=(await supabase.auth.getSession()).data.session?.user;if(!user){status.textContent='Connectez-vous avec le compte utilisé lors du paiement pour finaliser l’activation.';loader.hidden=true;return;}if(coaching){document.querySelector('[data-success-title]').textContent='Votre Coaching est en cours d’activation.';link.href='/coaching';link.innerHTML='Accéder à mon Coaching <span>→</span>';document.querySelector('[data-success-back]').href='/decouvrir-coaching';}for(let attempt=0;attempt<15;attempt++){const {data}=coaching?await supabase.rpc('has_coaching_access',{p_user_id:user.id}):await supabase.rpc('has_active_academy_access',{p_user_id:user.id});if(data){status.textContent='Votre espace est prêt.';loader.classList.add('complete');link.hidden=false;window.dispatchEvent(new CustomEvent(coaching?'stoa:coaching-purchase-completed':'stoa:academy-purchase-completed',{detail:{userId:user.id}}));return;}await wait(2000);}loader.hidden=true;status.textContent='La confirmation prend plus de temps que prévu. Votre paiement n’est pas perdu : actualisez cette page dans un instant ou contactez le support STOA.';}
initialize();
